
"use strict";

// INICIALIZAÇÃO DO BLOG
document.addEventListener("DOMContentLoaded", function() {
    console.log("⚽ Futebol Total iniciado!");

        atualizarAno();
            configurarPesquisa();
                configurarBotaoTopo();
                    configurarAnimacoes();
                    });

                    // 1. ATUALIZAR O ANO DO RODAPÉ
                    function atualizarAno() {
                        const ano = document.getElementById("ano");

                            if (ano) {
                                    ano.textContent = new Date().getFullYear();
                                        }
                                        }

                                        // 2. PESQUISAR NOTÍCIAS
                                        function configurarPesquisa() {
                                            const campo = document.getElementById("pesquisa");

                                                if (!campo) return;

                                                    campo.addEventListener("input", function() {
                                                            const termo = campo.value.toLowerCase().trim();
                                                                    const cards = document.querySelectorAll(".card");
                                                                            const aviso = document.getElementById("sem-resultados");

                                                                                    let encontrados = 0;

                                                                                            cards.forEach(function(card) {
                                                                                                        const texto = card.textContent.toLowerCase();
                                                                                                                    const corresponde = texto.includes(termo);

                                                                                                                                card.style.display = corresponde ? "" : "none";

                                                                                                                                            if (corresponde) {
                                                                                                                                                            encontrados++;
                                                                                                                                                                        }
                                                                                                                                                                                });

                                                                                                                                                                                        if (aviso) {
                                                                                                                                                                                                    aviso.hidden = encontrados > 0;
                                                                                                                                                                                                            }
                                                                                                                                                                                                                });
                                                                                                                                                                                                                }

                                                                                                                                                                                                                // 3. CURTIR UMA NOTÍCIA
                                                                                                                                                                                                                function curtir(botao) {
                                                                                                                                                                                                                    const contador = botao.querySelector("span");

                                                                                                                                                                                                                        if (!contador || botao.disabled) return;

                                                                                                                                                                                                                            let total = Number(contador.textContent) || 0;

                                                                                                                                                                                                                                total++;

                                                                                                                                                                                                                                    contador.textContent = total;
                                                                                                                                                                                                                                        botao.innerHTML = "❤️ Curtido! <span>" + total + "</span>";
                                                                                                                                                                                                                                            botao.disabled = true;

                                                                                                                                                                                                                                                botao.style.background = "#26994c";
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                // 4. COMPARTILHAR O BLOG
                                                                                                                                                                                                                                                async function compartilhar() {
                                                                                                                                                                                                                                                    const dados = {
                                                                                                                                                                                                                                                            title: "Futebol Total",
                                                                                                                                                                                                                                                                    text: "Confira este blog de futebol!",
                                                                                                                                                                                                                                                                            url: window.location.href
                                                                                                                                                                                                                                                                                };

                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                            if (navigator.share) {
                                                                                                                                                                                                                                                                                                        await navigator.share(dados);
                                                                                                                                                                                                                                                                                                                } else if (navigator.clipboard) {
                                                                                                                                                                                                                                                                                                                            await navigator.clipboard.writeText(dados.url);
                                                                                                                                                                                                                                                                                                                                        alert("Link copiado! Compartilhe com seus amigos.");
                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                            prompt("Copie o endereço do blog:", dados.url);
                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                        } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                if (erro.name !== "AbortError") {
                                                                                                                                                                                                                                                                                                                                                                                            alert("Não foi possível compartilhar agora.");
                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                        // 5. VOLTAR AO TOPO
                                                                                                                                                                                                                                                                                                                                                                                                        function voltarTopo() {
                                                                                                                                                                                                                                                                                                                                                                                                            window.scrollTo({
                                                                                                                                                                                                                                                                                                                                                                                                                    top: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                            behavior: "smooth"
                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                // 6. CONTROLAR O BOTÃO DO TOPO
                                                                                                                                                                                                                                                                                                                                                                                                                                function configurarBotaoTopo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                    const botao = document.getElementById("topo");

                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!botao) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                            function verificarPosicao() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.style.display =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                window.scrollY > 300 ? "block" : "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        window.addEventListener("scroll", verificarPosicao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            verificarPosicao();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 7. MODO ESCURO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function alternarModoEscuro() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.body.classList.toggle("escuro");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const ativo = document.body.classList.contains("escuro");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                localStorage.setItem(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "futebol-tema",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ativo ? "escuro" : "claro"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Não foi possível salvar a preferência.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 8. RECUPERAR O TEMA SALVO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function carregarModoEscuro() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const tema = localStorage.getItem("futebol-tema");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (tema === "escuro") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.body.classList.add("escuro");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (erro) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log("Preferência de tema indisponível.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 9. ANIMAÇÕES AO ROLAR A PÁGINA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function configurarAnimacoes() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const elementos = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ".card, .time, .sobre"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!("IntersectionObserver" in window)) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const observador = new IntersectionObserver(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function(entradas, observadorAtual) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    entradas.forEach(function(entrada) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (entrada.isIntersecting) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        entrada.target.style.opacity = "1";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            entrada.target.style.transform = "translateY(0)";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                observadorAtual.unobserve(entrada.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            { threshold: 0.1 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    elementos.forEach(function(elemento) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            elemento.style.opacity = "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    elemento.style.transform = "translateY(15px)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            elemento.style.transition = "opacity 0.5s, transform 0.5s";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    observador.observe(elemento);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 10. MOSTRAR A DATA ATUAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function mostrarData() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const hoje = new Date();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return hoje.toLocaleDateString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        day: "2-digit",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                month: "long",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        year: "numeric"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 11. CONTAR AS NOTÍCIAS VISÍVEIS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function contarNoticias() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const cards = document.querySelectorAll(".card");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Array.from(cards).filter(function(card) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return card.style.display !== "none";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }).length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // 12. LIMPAR A PESQUISA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function limparPesquisa() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const campo = document.getElementById("pesquisa");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (campo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                campo.value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        campo.dispatchEvent(new Event("input"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // CARREGAR A PREFERÊNCIA DO USUÁRIO
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.addEventListener("DOMContentLoaded", carregarModoEscuro);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            